const int BTN_PIN = 2;
void setup() {
  pinMode(BTN_PIN, INPUT_PULLUP);
  Serial.begin(9600);
}
void loop() {
  bool isPressed = (digitalRead(BTN_PIN) == LOW);
  Serial.println(isPressed ? "PRESSED" : "RELEASED");
  delay(200);
}

